package com.powerliq.marketdata;
import com.powerliq.api.contracts.*;import java.time.*;import java.util.*;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class MarketDataExceptionHandler{private final Clock clock;public MarketDataExceptionHandler(Clock c){clock=c;}@ExceptionHandler(ServiceException.class)ResponseEntity<ApiError> service(ServiceException e){return ResponseEntity.status(e.descriptor().httpStatus()).body(error(e.descriptor().code(),e.getMessage(),e.descriptor().retryable()));}@ExceptionHandler(Exception.class)ResponseEntity<ApiError> unexpected(){return ResponseEntity.internalServerError().body(error("INTERNAL_ERROR","An unexpected error occurred",false));}private ApiError error(String c,String m,boolean r){return new ApiError(c,m,"market-data-service",UUID.randomUUID().toString(),Instant.now(clock),r,List.of());}}
